func TestCompute_MarksGeneratedOffenders(t *testing.T) {
	eng := newTestEngine(t)
	eng.Store().Add(fixtureFacts()...)
	eng.Store().Add(
		// Generated by its banner: the path says nothing.
		facts.Fact{Kind: facts.KindSymbol, Name: "pkg/parse.lex", File: "pkg/parse/parser.c",
			Props: map[string]any{"symbol_kind": facts.SymbolFunc, "generated": true}},
		facts.Fact{Kind: facts.KindSymbol, Name: "pkg/parse.Parse", File: "pkg/parse/parse.go",
			Props: map[string]any{"symbol_kind": facts.SymbolFunc}},
	)
	eng.Store().BuildGraph()
	eng.SetSnapshot(&facts.Snapshot{Insights: []facts.Insight{
		{Title: "High cyclomatic complexity: pkg/parse.lex (900)", Confidence: 0.7},
		{Title: "High cyclomatic complexity: pkg/parse.Parse (108)", Confidence: 0.7},
		// Generated by its path alone, with no fact behind the name.
		{Title: "Deep dependency chain: internal/gen/api (depth 9)", Confidence: 0.6},
		{Title: "Deep dependency chain: cmd/app (depth 8)", Confidence: 0.9},
	}})
	r := Compute(eng)

	bySource := map[string]FindingGroup{}
	for _, g := range r.CodeHealth {
		bySource[g.Source] = g
	}
	cx := bySource["complexity-outliers"]
	if !cx.Top[0].Generated || cx.Top[1].Generated {
		t.Errorf("complexity: want lex generated and Parse not, got %+v", cx.Top)
	}
	deep := bySource["dependency-depth"]
	if !deep.Top[0].Generated || deep.Top[1].Generated {
		t.Errorf("depth: want internal/gen/api generated and cmd/app not, got %+v", deep.Top)
	}
	if deep.Confidence != 0.9 {
		t.Errorf("group confidence is the highest of its findings: got %v, want 0.9", deep.Confidence)
	}
}

func TestSummary_EverySectionIsFilled(t *testing.T) {
	s := summarize(&Report{}, nil)
	sections := map[string][]Item{
		"about": s.About, "health": s.Health.Items, "start here": s.StartHere,
		"careful": s.Careful, "worth a look": s.WorthALook, "caveats": s.Caveats, "next": s.Next,
	}
	for name, items := range sections {
		if len(items) == 0 {
			t.Errorf("section %q is empty; a reader cannot tell it from one enola never looked at", name)
		}
	}
	if s.Health.Verdict == "" {
		t.Error("health has no verdict")
	}
}

func TestSummary_IsDeterministic(t *testing.T) {
	r := summaryReport()
	if a, b := summarize(r, nil), summarize(r, nil); !reflect.DeepEqual(a, b) {
		t.Errorf("same report, different summaries:\n%+v\n%+v", a, b)
	}
}

func TestSummary_HealthVerdict(t *testing.T) {
	cases := []struct {
		name    string
		r       Report
		verdict string
		certain Certainty
		says    string
	}{
		{"clean", Report{Architecture: "go-standard", ArchConfidence: 0.85}, VerdictHealthy, Certain, "no layer rule broken"},
		{"no layout to check against", Report{}, VerdictHealthy, Certain, "could not be checked"},
		{"cycles", Report{Cycles: 2}, VerdictAttention, Certain, "2 circular dependencies"},
		{"guessed layers", Report{LayerViolations: 1, Architecture: "hexagonal", ArchConfidence: 0.8}, VerdictAttention, Likely, "1 place where"},
		{"declared layers", Report{LayerViolations: 3, Architecture: "declared (repo)", ArchConfidence: 1}, VerdictAttention, Certain, "3 places where"},
		// Zero findings over imports nobody could follow is not good news.
		{"blind", Report{CouplingUnresolved: true}, VerdictUnknown, Certain, "cannot judge"},
	}
	for _, c := range cases {
		h := summarize(&c.r, nil).Health
		if h.Verdict != c.verdict {
			t.Errorf("%s: verdict %q, want %q", c.name, h.Verdict, c.verdict)
		}
		if h.Items[0].Certainty != c.certain || !strings.Contains(h.Items[0].Text, c.says) {
			t.Errorf("%s: got %+v, want %s and %q", c.name, h.Items[0], c.certain, c.says)
		}
	}
}

func TestSummary_CarefulScalesWithRepositorySize(t *testing.T) {
	r := &Report{Modules: 100, Hotspots: []Hotspot{
		{Module: "pkg/small", BlastRadius: 9},
		{Module: "pkg/core", BlastRadius: 12},
		{Module: "vendor/lib", BlastRadius: 50, Generated: true},
	}}
	got := summarize(r, nil).Careful
	if len(got) != 1 || got[0].Subject != "pkg/core" {
		t.Fatalf("with 100 modules the bar is 10, and generated code is left out: got %+v", got)
	}
	if got[0].Next != "enola impact pkg/core" {
		t.Errorf("next: got %q", got[0].Next)
	}

	// In a small repository the floor holds: reaching 3 of 10 modules is local.
	small := &Report{Modules: 10, Hotspots: []Hotspot{{Module: "a", BlastRadius: 3}}}
	if got := summarize(small, nil).Careful; got[0].Subject != "" || !strings.Contains(got[0].Text, "No module stands out") {
		t.Errorf("small repository: got %+v", got)
	}
}

func TestSummary_WorthALookIsMostCertainFirst(t *testing.T) {
	s := summarize(summaryReport(), nil)
	want := []string{"pkg/x.Hub", "", "pkg/x.Parse"} // certain, likely (dead code), likely
	if len(s.WorthALook) != len(want) {
		t.Fatalf("got %d items, want %d: %+v", len(s.WorthALook), len(want), s.WorthALook)
	}
	for i, it := range s.WorthALook {
		if it.Subject != want[i] {
			t.Errorf("item %d: subject %q, want %q (%+v)", i, it.Subject, want[i], it)
		}
	}
	if s.WorthALook[0].Certainty != Certain {
		t.Errorf("first item should be certain, got %q", s.WorthALook[0].Certainty)
	}
	// The performance finding, a guess, did not fit and is counted.
	if s.MoreFindings != 1 {
		t.Errorf("MoreFindings = %d, want 1", s.MoreFindings)
	}
}

func TestSummary_SkipsGeneratedOffenders(t *testing.T) {
	s := summarize(summaryReport(), nil)
	for _, it := range s.WorthALook {
		if it.Subject == "pkg/gen.lex" {
			t.Errorf("generated code ranked as worth a look: %+v", it)
		}
	}
	if !containsText(s.Caveats, "1 top-ranked finding is in generated or vendored code") {
		t.Errorf("the summary must say what it left out, got %+v", s.Caveats)
	}
	if last := s.Caveats[len(s.Caveats)-1]; !strings.Contains(last.Text, "never runs it") {
		t.Errorf("last caveat should be what enola cannot see, got %+v", last)
	}
}

func TestSummary_StartHere(t *testing.T) {
	r := &Report{Hotspots: []Hotspot{
		{Module: "pkg/glue", FanIn: 1, FanOut: 90},
		{Module: "pkg/rare", FanIn: careFloor - 1},
		{Module: "internal/facts", FanIn: 345, FanOut: 1},
		{Module: "vendor/big", FanIn: 900, Generated: true},
	}}
	entries := []entryPoint{{name: "cmd/app.main", file: "cmd/app/main.go", line: 12, mechanism: "main", reach: 40, modules: 6}}
	got := summarize(r, entries).StartHere
	if len(got) != 2 {
		t.Fatalf("want the entry and the core, got %+v", got)
	}
	if got[0].Subject != "cmd/app.main" || got[0].Location != "cmd/app/main.go:12" || !strings.Contains(got[0].Text, "starts here") {
		t.Errorf("entry: got %+v", got[0])
	}
	if got[1].Subject != "internal/facts" || !strings.Contains(got[1].Text, "imported 345 times") {
		t.Errorf("core is the most imported module that is not generated: got %+v", got[1])
	}

	if got := summarize(r, nil).StartHere; !strings.Contains(got[0].Text, "no clear starting point") || got[1].Subject != "internal/facts" {
		t.Errorf("no entries: got %+v", got)
	}
}

func TestSummarize_FindsTheProgramsEntry(t *testing.T) {
	eng := newTestEngine(t)
	eng.Store().Add(fixtureFacts()...)
	eng.Store().Add(facts.Fact{Kind: facts.KindSymbol, Name: "cmd/app.main", File: "cmd/app/main.go", Line: 3,
		Props:     map[string]any{"symbol_kind": facts.SymbolFunc},
		Relations: []facts.Relation{{Kind: facts.RelCalls, Target: "internal/a.DoThing"}}})
	eng.Store().BuildGraph()
	eng.SetSnapshot(&facts.Snapshot{Meta: facts.SnapshotMeta{RepoPath: "/repo/demo"}})

	s := Summarize(eng, Compute(eng))
	if s.StartHere[0].Subject != "cmd/app.main" || s.StartHere[0].Location != "cmd/app/main.go:3" {
		t.Errorf("start here: got %+v", s.StartHere)
	}
	if s.Next[0].Subject != "enola --explain /repo/demo" {
		t.Errorf("next: got %+v", s.Next)
	}
}

func TestSummary_About(t *testing.T) {
	r := &Report{
		Languages: []string{"go", "c", "typescript"}, Modules: 1,
		SymbolKinds:  []LabelCount{{Label: "function", Count: 10}, {Label: "section", Count: 99}},
		RoutesServed: 1, RoutesOutbound: 3,
		Architectures:  []ArchitectureStatement{{Pattern: "declared (repo)", Confidence: 1}},
		DeclaredLayers: 6, LayerFiles: []string{"enola-intent.yaml"},
	}
	about := summarize(r, nil).About
	for _, want := range []string{
		"Written mainly in Go, also C and TypeScript.",
		"1 module (a folder of code), holding 10 named pieces of code",
		"Serves 1 HTTP endpoint and calls 3 outside ones. enola found no database or other data store.",
		"writes down which parts of its code may use which (6 layers, in enola-intent.yaml), and enola checks every import against it.",
	} {
		if !containsText(about, want) {
			t.Errorf("about is missing %q: %+v", want, about)
		}
	}
}

// summaryReport has one finding of each kind WorthALook reads, at known
// certainties, and a generated offender ranked above a real one.
func summaryReport() *Report {
	return &Report{
		Modules: 20,
		CodeHealth: []FindingGroup{
			{Source: "god-class", Count: 1, Confidence: 0.95, Top: []RankedItem{{Name: "pkg/x.Hub", Detail: "80 dependents"}}},
			{Source: "complexity-outliers", Count: 2, Confidence: 0.7, Top: []RankedItem{
				{Name: "pkg/gen.lex", Detail: "complexity 900", Generated: true},
				{Name: "pkg/x.Parse", Detail: "complexity 108"},
			}},
		},
		DeadCode:    &orphans.Summary{High: 4},
		Performance: &perf.Summary{High: 7},
	}
}

func containsText(items []Item, s string) bool {
	for _, it := range items {
		if strings.Contains(it.Text, s) {
			return true
		}
	}
	return false
}

func TestSummaryRender_SectionsInFixedOrder(t *testing.T) {
	out := summarize(&Report{RepoPath: "/repo/x"}, nil).Render()
	last := -1
	for _, h := range []string{
		"Repository summary: /repo/x", "What this is", "Structure: healthy", "Start reading here",
		"Careful when changing", "Worth a look (most certain first)", "Take with a grain of salt", "Next",
	} {
		i := strings.Index(out, h)
		if i <= last {
			t.Fatalf("heading %q missing or out of order in:\n%s", h, out)
		}
		last = i
	}
}

func TestSummaryRender_OnlyHedgesAreLabelled(t *testing.T) {
	out := summarize(summaryReport(), nil).Render()
	if strings.Contains(out, "(certain)") {
		t.Errorf("certain statements are printed as they are:\n%s", out)
	}
	for _, want := range []string{"(likely)", "1 more kind of finding is in the full report."} {
		if !strings.Contains(out, want) {
			t.Errorf("missing %q in:\n%s", want, out)
		}
	}
	guess := summarize(&Report{Performance: &perf.Summary{High: 2}}, nil).Render()
	if !strings.Contains(strings.Join(strings.Fields(guess), " "), "grows large. (a guess)") {
		t.Errorf("a guess is labelled as one:\n%s", guess)
	}
}

func TestSummaryRender_WrapsAtWidth(t *testing.T) {
	var b strings.Builder
	wrap(&b, strings.Repeat("word ", 40), "  ", "    ")
	lines := strings.Split(strings.TrimSuffix(b.String(), "\n"), "\n")
	if len(lines) < 2 {
		t.Fatalf("expected wrapping, got %q", b.String())
	}
	for i, l := range lines {
		if len(l) > summaryWidth {
			t.Errorf("line %d is %d wide: %q", i, len(l), l)
		}
	}
	if !strings.HasPrefix(lines[1], "    word") {
		t.Errorf("continuation indent: %q", lines[1])
	}
}

func TestSummary_NoCoreInASmallRepository(t *testing.T) {
	r := &Report{Hotspots: []Hotspot{{Module: "pkg/a", FanIn: 2}}}
	for _, it := range summarize(r, nil).StartHere {
		if it.Subject == "pkg/a" {
			t.Errorf("a module imported twice is not what the code builds on: %+v", it)
		}
	}
}

func TestCompute_StorageSeparatesStoresFromQueries(t *testing.T) {
	eng := newTestEngine(t)
	ref := func(name string) facts.Fact {
		return facts.Fact{Kind: facts.KindStorage, Name: name, File: "db/q.go", Props: map[string]any{"storage_kind": "table_reference"}}
	}
	eng.Store().Add(
		facts.Fact{Kind: facts.KindStorage, Name: "users", File: "db/m1.sql", Props: map[string]any{"storage_kind": "table"}},
		// The same table created again by a later migration is still one table.
		facts.Fact{Kind: facts.KindStorage, Name: "users", File: "db/m2.sql", Props: map[string]any{"storage_kind": "table"}},
		facts.Fact{Kind: facts.KindStorage, Name: "uploads", File: "infra/s3.tf", Props: map[string]any{"storage_kind": "s3"}},
		ref("users"), ref("users"), ref("AllExpenses"),
	)
	eng.Store().BuildGraph()
	r := Compute(eng)
	if r.Storage != 6 || r.StorageDistinct != 2 || r.StorageReferences != 3 {
		t.Errorf("storage = %d, distinct = %d, references = %d; want 6, 2, 3", r.Storage, r.StorageDistinct, r.StorageReferences)
	}
	if about := summarize(r, nil).About; !containsText(about, "Works with 2 distinct data stores") {
		t.Errorf("about: %+v", about)
	}
	if about := summarize(&Report{StorageReferences: 3}, nil).About; !containsText(about, "defined somewhere else") {
		t.Errorf("queries without stores: %+v", about)
	}
}

func TestSummary_OneUnusedFunctionReadsAsOne(t *testing.T) {
	items, _ := worthALook(&Report{DeadCode: &orphans.Summary{High: 1}})
	if !strings.HasPrefix(items[0].Text, "1 function looks unused. Check it before deleting it:") {
		t.Errorf("got %q", items[0].Text)
	}
}

func TestSummaryRender_LongSubjectPutsLocationOnItsOwnLine(t *testing.T) {
	var b strings.Builder
	long := strings.Repeat("a", summaryWidth)
	section(&b, "Start reading here", []Item{{Subject: long, Location: "x.ts:3", Text: "t", Certainty: Certain}}, "")
	if !strings.Contains(b.String(), "  "+long+"\n    at x.ts:3\n") {
		t.Errorf("got:\n%s", b.String())
	}
}

func TestCompute_DeclaredLayersAndWhere(t *testing.T) {
	eng := newTestEngine(t)
	layer := func(name, file string) facts.Fact {
		return facts.Fact{Kind: facts.KindIntent, Name: "layer " + name, File: file,
			Props: map[string]any{"intent_kind": "layer", "layer_name": name}}
	}
	eng.Store().Add(layer("app", "enola-intent.yaml"), layer("core", "enola-intent.yaml"),
		facts.Fact{Kind: facts.KindIntent, Name: "rule", File: "enola-intent.yaml", Props: map[string]any{"intent_kind": "constraint"}})
	eng.Store().BuildGraph()
	r := Compute(eng)
	if r.DeclaredLayers != 2 || !reflect.DeepEqual(r.LayerFiles, []string{"enola-intent.yaml"}) {
		t.Errorf("layers = %d in %v, want 2 in [enola-intent.yaml]", r.DeclaredLayers, r.LayerFiles)
	}
}
